/**
 * Generates supabase/seed.sql from the typed course content in src/content.
 * The catalog tables let the database enforce that progress rows reference real lessons.
 * Run: npm run seed:generate   (then apply with `supabase db reset` or paste into the SQL editor)
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { modules } from "../src/content";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

const lines: string[] = [
  "-- GENERATED by scripts/generate-seed.ts — do not edit by hand.",
  "-- Course catalog. Safe to re-run (upserts).",
  "begin;",
];
for (const m of modules) {
  lines.push(
    `insert into public.course_modules (id, number, title) values (${q(m.id)}, ${m.number}, ${q(m.title)}) on conflict (id) do update set number = excluded.number, title = excluded.title;`,
  );
  m.lessons.forEach((l, i) =>
    lines.push(
      `insert into public.course_lessons (id, module_id, position, title) values (${q(l.id)}, ${q(m.id)}, ${i + 1}, ${q(l.title)}) on conflict (id) do update set module_id = excluded.module_id, position = excluded.position, title = excluded.title;`,
    ),
  );
}
lines.push("commit;", "");

const out = join(process.cwd(), "supabase", "seed.sql");
writeFileSync(out, lines.join("\n"));
console.log(`Wrote ${out} (${modules.length} modules, ${modules.reduce((n, m) => n + m.lessons.length, 0)} lessons)`);
